  const P = list => list.map(a => Object.assign({ region: "mumbai", story: null, jargon: [], mis: [] }, a));

  MV.ASSETS.push(...P([
  { id: "mw-bmc-budget", type: "fact", domain: "economics", title: "The BMC: India's richest city government", value: 4, cue: "potholes, property tax, or who runs Mumbai",
    emoji: "🏛️", wiki: "Brihanmumbai Municipal Corporation",
    fact: "The Brihanmumbai Municipal Corporation, or BMC, is the richest city government in India. Its budget for 2026-27 is about 80,952 crore rupees. That is larger than the budget of several Indian states.",
    why: "Roads, drains, water, schools, hospitals and garbage in Mumbai all depend on this one body. When it works well or badly, 1.2 crore people feel it the same day.",
    mech: "The BMC earns from property tax, from fees on new buildings, and from a share of GST that replaced the old octroi tax on goods entering the city. Mumbai has very high land prices, so these taxes bring in huge sums. The money also goes far because the city is small and dense. One drain or one road serves many thousands of people. The BMC also keeps large fixed deposits, which earn interest every year.",
    models: ["compounding", "incentives"],
    q: "Why is the BMC so much richer than other city governments in India?",
    a: "Mumbai's land is very costly, so property tax and building fees bring in huge sums. The BMC also gets a GST share that replaced octroi, and it earns interest on large deposits. Its budget is about 80,952 crore rupees.",
    chain: [["Very high land prices", ["land", "costly", "expensive", "price"]], ["Property tax and building fees", ["property tax", "building", "fee", "premium"]], ["GST share replaced octroi", ["gst", "octroi"]], ["A budget of about 80,952 crore", ["80,952", "81,000", "crore", "budget"]]],
    mcq: { q: "What is the BMC's approximate budget for 2026-27?", o: ["About 81,000 crore rupees", "About 8,000 crore rupees", "About 800 crore rupees", "About 8 lakh crore rupees"] },
    bring: "When someone curses a pothole: “The BMC has a budget of over 80,000 crore. The money is not the problem.”",
    follow: "If you ran the BMC for one year, what would you fix first?",
    deeper: "Before 2017 the BMC's biggest income was octroi, a tax on every truck of goods entering the city. GST ended octroi, and the state now pays the BMC a fixed compensation instead." },

  { id: "mw-metro-aqua", type: "concept", domain: "geography", title: "Metro Line 3 and the Aarey car shed", value: 4, cue: "the metro, Aarey, or trees versus transport",
    emoji: "🚇", wiki: "Aqua Line (Mumbai Metro)",
    fact: "Metro Line 3, the Aqua Line, is Mumbai's first fully underground metro. Its 33.5 km from Cuffe Parade to Aarey opened in stages and was fully open on 9 October 2025. Where to park its trains became one of the city's longest public debates.",
    why: "A metro needs a car shed, a large depot where trains rest at night. The one planned inside Aarey forest set the need for transport against the need for green land.",
    mech: "An underground line still needs a large flat plot above ground for its depot. The planners chose Aarey Milk Colony, a green area next to the national park. In October 2019 about 2,141 trees were cut there in one night before the Supreme Court stopped more felling. In 2020 the state moved the shed to Kanjurmarg, but that land was tied up in a court dispute. In 2022 a new state government moved it back to Aarey. The line opened with its depot at Aarey.",
    models: ["opportunity-cost", "second-order-thinking"],
    q: "Why did a metro line cause a fight about a forest?",
    a: "Every metro needs a big depot to park trains, and Line 3's was planned inside Aarey. About 2,141 trees were cut in 2019 before the Supreme Court stepped in. The shed moved to Kanjurmarg and then back to Aarey, and the full line opened in October 2025.",
    chain: [["A metro needs a depot to park trains", ["depot", "car shed", "shed", "park"]], ["It was planned inside Aarey", ["aarey", "forest", "green"]], ["Trees cut in 2019, then court action", ["2,141", "2019", "trees", "supreme court", "court"]], ["Moved to Kanjurmarg, then back; line fully open 2025", ["kanjurmarg", "moved", "back", "2025"]]],
    mcq: { q: "Why did Metro Line 3 need land inside Aarey?", o: ["For a depot where its trains are parked and serviced", "For a station serving the milk colony", "For a power plant to run the trains", "For a bridge across the Mithi river"] },
    bring: "When the metro comes up: “The whole Aarey fight was about one thing: where the trains sleep at night.”",
    follow: "How would you decide between saving trees and finishing a metro faster?",
    deeper: "Line 3 cost over 37,000 crore rupees and has 27 stations. Mumbai's first metro, Line 1 from Versova to Ghatkopar, opened on 8 June 2014. By 2026 the city had about 100 km of working metro." },

  { id: "mw-monorail", type: "concept", domain: "strategy", title: "The monorail that nobody rode", value: 4, cue: "white elephants, government projects, or the Chembur monorail",
    emoji: "🚝", wiki: "Mumbai Monorail",
    fact: "India's first monorail opened in Mumbai on 2 February 2014, from Chembur to Wadala. Planners expected over 1.5 lakh riders a day. It got around 15,000, about one tenth. In its first two years it lost about 159 crore rupees.",
    why: "It shows that a transport line is only useful if it goes where people already want to go, and connects to the trains they already use.",
    mech: "The route ran through Wadala and Chembur, areas with few offices and poor links to the local train stations. People had to walk far to switch lines, so most kept using buses. Low ridership meant low fares collected, but the trains and staff cost the same. Then came breakdowns. In August 2025 two crowded trains stalled in the rain and about 800 people had to be rescued. Services were suspended from 20 September 2025 for new trains and safety work.",
    models: ["network-effects", "survivorship-bias", "map-vs-territory"],
    q: "Why did the Mumbai monorail fail to attract riders?",
    a: "Its route from Chembur to Wadala ran through areas with few offices and did not connect well to local train stations. So it got about 15,000 riders a day instead of 1.5 lakh, lost money, and later suffered breakdowns and a suspension.",
    chain: [["Opened 2014, Chembur to Wadala", ["2014", "chembur", "wadala"]], ["Poor links to train stations and offices", ["connect", "link", "station", "offices", "walk"]], ["One tenth of expected riders", ["15,000", "tenth", "10%", "1.5 lakh", "ridership", "riders"]], ["Losses and breakdowns, suspended 2025", ["loss", "lost", "breakdown", "stalled", "suspend", "2025"]]],
    mcq: { q: "About what share of its expected riders did the monorail actually get?", o: ["About one tenth", "About half", "Almost all of them", "About twice as many"] },
    bring: "When a new project is announced: “The monorail had every forecast in its favour. It got one rider in ten. A line is only as good as its connections.”",
    follow: "Which new road or line near you do you think will actually be used?",
    deeper: "The full 19.5 km line to Jacob Circle, near Mahalaxmi, opened only in March 2019. In 2026 the MMRDA was still waiting for a report from IIT Bombay on how to cover gaps between the two beams before trains could run again." },

  { id: "mw-last-tram", type: "historical story", domain: "history", title: "The last tram of Bombay, 1964", value: 4, cue: "old Bombay, BEST buses, or things that disappear", story: "lasttram",
    emoji: "🚋", wiki: "Trams in India",
    fact: "Bombay had trams for 90 years. Horse-drawn trams began in 1874 and electric trams in 1907. At 10 pm on 31 March 1964 the last tram left Bori Bunder for Dadar, packed with people who came to say goodbye.",
    why: "The T in BEST still stands for Tramways. A system that carried the city for three generations vanished in one night, and the reason was simple arithmetic.",
    mech: "Trams ran on fixed rails in the middle of the road. As cars, buses and trucks multiplied after 1947, the trams slowed everything and were slowed themselves. A tram could not go around a stopped lorry. Buses could use any road and needed no rails or wires to maintain. From 1953 BEST closed tram routes one by one and put buses on them. By 1964 the last route was gone.",
    models: ["opportunity-cost", "bottlenecks"],
    q: "Why did Bombay give up its trams?",
    a: "Trams ran on fixed rails in the middle of busy roads, so growing motor traffic jammed them and they jammed the traffic. Buses could use any road without rails. BEST closed routes from 1953 and the last tram ran on 31 March 1964.",
    chain: [["Trams ran on fixed rails in the road", ["rail", "fixed", "track", "middle of the road"]], ["Motor traffic grew and jammed them", ["traffic", "cars", "lorry", "jam", "slow"]], ["Buses were cheaper and more flexible", ["bus", "any road", "flexible", "cheaper", "no rails"]], ["Last tram on 31 March 1964", ["1964", "last tram", "dadar", "bori bunder"]]],
    mcq: { q: "When did Bombay's last tram run?", o: ["31 March 1964", "15 August 1947", "1 May 1960", "26 January 1980"] },
    bring: "On a BEST bus: “The T in BEST is for Tramways. The last tram ran in 1964, and people hung from the windows to ride it.”",
    follow: "What everyday thing in Mumbai today do you think will be gone in 30 years?",
    deeper: "The Bombay Electric Supply and Tramways Company took over the trams in 1905 and ran the city's electricity too. It became a municipal body in 1947. BEST still supplies electricity to the island city." },

  { id: "mw-auto-line", type: "concept", domain: "economics", title: "Why autos stop at Bandra and Sion", value: 4, cue: "rickshaws, taxis, or South Mumbai rules",
    emoji: "🛺", wiki: "Auto rickshaw",
    fact: "Auto-rickshaws may not drive south of Bandra on the western side or Sion on the central side. The island city is left to black-and-yellow taxis. The rule has existed for decades and is enforced with fines.",
    why: "It is one of the clearest cases of a city dividing a market by drawing a line on the map. Two groups of drivers each get a protected area.",
    mech: "Autos came to Bombay's suburbs in the 1960s, when the island city already had a large taxi trade. The old city's roads are narrow and crowded, and officials argued that three-wheelers would add to jams. The taxi unions also did not want cheaper rivals. So permits for autos were given only for the suburbs. Over time this became a hard boundary. Taxis may go anywhere, but autos must stop at the line.",
    models: ["incentives", "game-theory"],
    q: "Why are there no auto-rickshaws in South Mumbai?",
    a: "Autos arrived in the suburbs when the island city already had many taxis. Officials said the narrow old roads would jam, and taxi unions did not want cheaper rivals. So auto permits were given only for the suburbs, with the boundary at Bandra and Sion.",
    chain: [["The island city already had a taxi trade", ["taxi", "already", "trade"]], ["Narrow roads and fear of jams", ["narrow", "jam", "crowd", "congest"]], ["Taxi unions resisted cheaper rivals", ["union", "rival", "cheaper", "protect"]], ["Permits only for the suburbs; line at Bandra and Sion", ["permit", "suburb", "bandra", "sion", "line"]]],
    mcq: { q: "Up to where can auto-rickshaws run on Mumbai's western side?", o: ["Bandra", "Churchgate", "Dadar", "Colaba"] },
    bring: "When a visitor asks for an auto at CST: “Autos cannot cross Bandra or Sion. South of that line, it is taxis only.”",
    follow: "Do you think the auto line protects the city, or only the taxi trade?",
    deeper: "Many Indian cities have no such line. Mumbai also stopped giving new auto permits for long periods, which created a black market where a permit could cost lakhs of rupees." },

  { id: "mw-padmini", type: "fact", domain: "history", title: "The Premier Padmini retires, 2023", value: 3, cue: "kaali-peeli taxis, old cars, or Bollywood",
    emoji: "🚕", wiki: "Premier Padmini",
    fact: "The Premier Padmini was Mumbai's black-and-yellow taxi for almost 60 years. The last one was registered on 29 October 2003. Mumbai allows taxis to run for only 20 years, so from 30 October 2023 not one Padmini was left in service.",
    why: "A car that stopped being made in 2001 kept running for 22 more years. It did not die of old age. A rule killed it on a fixed date.",
    mech: "Premier Automobiles made the Padmini in Kurla, just outside the island city, from the 1960s. It was small, cheap to repair, and every mechanic knew it. Taxi drivers kept buying them even after production stopped in 2001. But Maharashtra set a 20-year age limit on taxis to cut pollution. Count 20 years from the last registration in 2003 and you get 2023. The whole fleet aged out together.",
    models: ["second-order-thinking", "lindy-effect"],
    q: "Why did the last Premier Padmini taxi leave the road exactly in October 2023?",
    a: "Production ended in 2001 and the last taxi was registered in October 2003. Maharashtra allows taxis to run only 20 years, so 20 years after that date the last one had to retire.",
    chain: [["Made in Kurla from the 1960s", ["kurla", "1960", "premier", "made"]], ["Production stopped in 2001", ["2001", "stopped", "ended"]], ["A 20-year age limit on taxis", ["20 year", "20-year", "age limit", "twenty"]], ["Last one registered 2003, gone in 2023", ["2003", "2023", "retire", "last"]]],
    mcq: { q: "What rule removed the last Premier Padmini taxi from Mumbai's roads?", o: ["A 20-year age limit on taxis", "A ban on petrol cars", "A ban on black-and-yellow colours", "A court order against noisy engines"] },
    bring: "When old Bombay comes up: “The Padmini taxi outlived its own factory by 22 years. A 20-year rule finally retired it in 2023.”",
    follow: "Would you rather have a familiar old car or a new one nobody knows how to fix?",
    deeper: "The Padmini was based on the Italian Fiat 1100. The double-decker diesel buses of BEST also retired in 2023, so the city lost two icons in one year." },

  { id: "mw-cheap-fare", type: "fact", domain: "economics", title: "A train ride for five rupees", value: 4, cue: "ticket prices, subsidies, or how the poor get to work",
    emoji: "🎫", wiki: "Mumbai Suburban Railway",
    fact: "The cheapest second-class ticket on a Mumbai local costs 5 rupees. A monthly pass can cost a few hundred rupees. Per kilometre, this is among the lowest public transport fares anywhere in the world.",
    why: "A low fare is why a domestic worker from Virar can hold a job in Churchgate, 60 km away. The fare is a social policy as much as a price.",
    mech: "Indian Railways keeps suburban fares low on purpose and makes up the loss from freight and long-distance tickets. Mumbai's local fares were not raised for years at a time, so inflation made them cheaper in real terms. When Indian Railways raised fares in July 2025, the suburban trains were left out again. The cost is paid elsewhere: crowded coaches, old rakes, and slow upgrades.",
    models: ["opportunity-cost", "incentives"],
    q: "Why is a Mumbai local ticket so cheap, and what is the hidden cost?",
    a: "Indian Railways keeps suburban fares low on purpose and covers the loss with freight and long-distance earnings. The minimum second-class fare is 5 rupees. The hidden cost is crowding and slow upgrades, because fares bring in too little to pay for them.",
    chain: [["Minimum fare is 5 rupees", ["5 rupees", "five rupees", "rs 5", "cheap"]], ["Railways keep suburban fares low on purpose", ["purpose", "policy", "kept low", "not raised", "left out"]], ["Freight and long-distance fares cover the loss", ["freight", "long-distance", "cover", "cross"]], ["Hidden cost: crowding and slow upgrades", ["crowd", "upgrade", "old", "hidden"]]],
    mcq: { q: "What is the minimum second-class fare on a Mumbai local?", o: ["5 rupees", "20 rupees", "50 rupees", "1 rupee"] },
    bring: "When someone complains about train crowds: “The ticket costs 5 rupees. We are getting what we pay for, and that is the point.”",
    follow: "Would you pay double for a less crowded train?",
    deeper: "A cheap fare also shapes where people live. Families move far north to Virar or Badlapur because the extra distance costs almost nothing in fare, only in time." },

  { id: "mw-jnpt", type: "business concept", domain: "business", title: "JNPT: the port that took over from Mumbai", value: 4, cue: "imports, shipping, or Navi Mumbai",
    emoji: "🚢", wiki: "Jawaharlal Nehru Port",
    fact: "Jawaharlal Nehru Port at Nhava Sheva, across the harbour from Mumbai, opened in 1989. In 2024-25 it handled 7.3 million containers, more than half of all containers passing through India's major ports. The old Mumbai Port lost almost all its container trade to it.",
    why: "Most of what Mumbai imports and exports no longer touches Mumbai. It lands across the water, in Raigad district.",
    mech: "Container ships grew huge in the 1970s and 1980s. Mumbai Port had shallow water, old enclosed docks with lock gates, and no room for container yards. Trucks from the docks had to cross the crowded city. Nhava Sheva had deep water and empty land on the mainland side. So the central government built a new port there to take the load off Mumbai. Once shipping lines moved, the container cranes, customs agents and warehouses followed.",
    models: ["bottlenecks", "network-effects"],
    q: "Why did Mumbai's container trade move to Nhava Sheva?",
    a: "Mumbai Port had shallow water, old enclosed docks and no land for container yards, and its trucks jammed the city. JNPT at Nhava Sheva, opened in 1989, had deep water and space. It now handles over half of India's major-port containers.",
    chain: [["Mumbai Port was shallow and cramped", ["shallow", "cramped", "no room", "no land", "lock gate", "old"]], ["Trucks had to cross the crowded city", ["truck", "crowded city", "jam", "load off"]], ["JNPT opened 1989 with deep water and land", ["1989", "deep", "nhava", "space", "mainland"]], ["Now over half of India's major-port containers", ["half", "7.3", "million", "container", "largest"]]],
    mcq: { q: "About what share of India's major-port containers pass through JNPT?", o: ["More than half", "About one tenth", "About 5 percent", "Almost all of them"] },
    bring: "When imports come up: “Your phone probably did not land in Mumbai. It landed at JNPT, across the harbour. That port handles half of India's containers.”",
    follow: "What do you think the old Mumbai docks should become?",
    deeper: "The Atal Setu bridge, opened in 2024, was partly built to speed trucks between the city and JNPT. Mumbai Port now handles mostly liquids, cars and cruise ships." },

  { id: "mw-airport-runway", type: "concept", domain: "geography", title: "An airport with one runway and a slum next door", value: 4, cue: "flight delays, the airport, or land in Mumbai",
    emoji: "✈️", wiki: "Chhatrapati Shivaji Maharaj International Airport",
    fact: "Mumbai's airport has two runways, but they cross each other, so only one can be used at a time. It has handled about 1,000 flights in a day on a single runway, one every 65 seconds. Dense slums sit on hundreds of acres around the runway.",
    why: "It explains why flights are delayed, why a second airport was needed, and why airport land is one of the city's hardest problems.",
    mech: "The airport was built on flat land in Santacruz and Sahar in the 1940s, when the area was open. The city then grew around it on every side. There was no land for a second parallel runway, and the crossing runways cannot be used together. Meanwhile people settled on airport land that lay unused. Those settlements grew into slums with lakhs of residents. Moving them needs new housing, which needs land that does not exist nearby.",
    models: ["bottlenecks", "margin-of-safety"],
    q: "Why can Mumbai airport not simply add more flights?",
    a: "Its two runways cross, so only one works at a time, and the city has grown right up to the fence, leaving no land for a parallel runway. Dense slums also occupy airport land. The single runway is the bottleneck, handling about 1,000 flights a day at its peak.",
    chain: [["Two runways that cross", ["cross", "two runway", "intersect"]], ["Only one can be used at a time", ["one at a time", "single", "one runway", "only one"]], ["The city grew around it, no land left", ["grew around", "no land", "fence", "parallel"]], ["Slums on airport land", ["slum", "settle", "hutment"]]],
    mcq: { q: "Why does Mumbai airport use only one runway at a time?", o: ["Its two runways cross each other", "One runway is reserved for cargo", "There is only one air traffic controller", "The second runway is too short for jets"] },
    bring: "When your flight is late: “Mumbai runs a thousand flights a day on one runway. The second one crosses it, so it cannot be used at the same time.”",
    follow: "Where would you have put a second airport if you were planning in 1970?",
    deeper: "The main runway is 09/27 and the secondary is 14/32. Rehabilitation plans for the airport slums have been announced several times since the 2000s and cover over 20,000 families." },

  { id: "mw-navi-mumbai", type: "concept", domain: "geography", title: "Navi Mumbai: a twin city built on purpose", value: 4, cue: "Vashi, Panvel, the new airport, or city planning",
    emoji: "🏙️", wiki: "Navi Mumbai",
    fact: "Navi Mumbai was planned in the early 1970s as a twin city across the harbour. The state created CIDCO in 1970 to build it on about 344 square kilometres of land. In 2025 it got its own airport, opened on 8 October with flights from 25 December.",
    why: "It is one of the largest planned cities in the world, and it exists because Mumbai had run out of room.",
    mech: "By the 1960s Mumbai was a thin strip packed with people, with jobs piled up at the southern tip. Planners argued the city should grow across the harbour, not further north. CIDCO bought land from 95 villages and built nodes like Vashi, Nerul and Belapur. The Vashi bridge in 1973 and the harbour railway in the 1990s linked it to Mumbai. Growth was slow at first because jobs stayed in Mumbai. The wholesale markets, offices, and now the airport are pulling jobs across.",
    models: ["first-principles", "network-effects"],
    q: "Why was Navi Mumbai built, and why did it grow slowly?",
    a: "Mumbai had no room, so planners decided to grow across the harbour. CIDCO, set up in 1970, built nodes like Vashi and Belapur. It grew slowly because jobs stayed in Mumbai, and only bridges, trains, markets and now the 2025 airport pulled people and jobs across.",
    chain: [["Mumbai had run out of room", ["no room", "run out", "packed", "thin strip"]], ["CIDCO set up in 1970 to build across the harbour", ["cidco", "1970", "harbour", "across"]], ["Slow growth because jobs stayed in Mumbai", ["slow", "jobs stayed", "jobs"]], ["Links and the 2025 airport pull jobs across", ["bridge", "railway", "airport", "2025", "market"]]],
    mcq: { q: "Which agency was created to build Navi Mumbai?", o: ["CIDCO", "MHADA", "BMC", "MMRDA"] },
    bring: "When Navi Mumbai comes up: “It was drawn on paper in 1970 as a twin city. It took 50 years and an airport to really take off.”",
    follow: "Would you move across the harbour if your job did too?",
    deeper: "The architect Charles Correa and others proposed the twin city idea in 1964 in a famous article. The new airport at Ulwe was built by a company owned by Adani Airports and CIDCO." },

  { id: "mw-bkc", type: "business concept", domain: "business", title: "BKC: a business district built on a marsh", value: 4, cue: "offices, Nariman Point, or where the money moved",
    emoji: "🏢", wiki: "Bandra Kurla Complex",
    fact: "The Bandra Kurla Complex was low marshy land along the Mithi river. In 1977 the MMRDA was made its planning authority to develop about 370 hectares. Today it holds banks, stock market offices, consulates and the headquarters of big companies.",
    why: "Mumbai's centre of money moved 15 km north in about 30 years. It shows how a city can move its heart on purpose.",
    mech: "By the 1970s Nariman Point and Fort were full and rents were extreme. Every office worker had to travel to the southern tip, which jammed the trains in one direction. Planners wanted a new centre in the middle of the city, where western and central lines were both near. The Mithi marsh between Bandra and Kurla was empty because it flooded. The river was straightened into a channel and the land was raised. The MMRDA then sold plots at auction, which also paid for the roads.",
    models: ["bottlenecks", "second-order-thinking"],
    q: "Why was a new business district built at Bandra Kurla, and how?",
    a: "Nariman Point was full and every commute went to the southern tip. Planners chose empty marshland in the middle of the city near both railway lines. The Mithi was channelled, the land raised, and the MMRDA sold plots at auction from the late 1970s onwards.",
    chain: [["Nariman Point and Fort were full", ["nariman", "fort", "full", "extreme", "saturat"]], ["Everyone travelled to the southern tip", ["southern tip", "one direction", "commute", "travel"]], ["Marshland in the middle, near both rail lines", ["marsh", "middle", "both", "railway lines", "empty"]], ["Mithi channelled, land raised, plots auctioned", ["channel", "raised", "auction", "sold", "1977"]]],
    mcq: { q: "What was the land of BKC before it became offices?", o: ["Low marshland along the Mithi river", "A textile mill compound", "A military airfield", "A quarry for building stone"] },
    bring: "When office rents come up: “BKC was a swamp in 1977. Now it is where the banks sit. Mumbai moved its money north on purpose.”",
    follow: "Where do you think Mumbai's next business centre will be?",
    deeper: "Raising and squeezing the Mithi here is one reason some blame BKC for worse flooding upstream, including in 2005. The MMRDA has earned tens of thousands of crore rupees from BKC plot sales." },

  { id: "mw-coastal-road", type: "fact", domain: "design", title: "The Coastal Road and the tunnel under Malabar Hill", value: 3, cue: "driving to town, Marine Drive, or new infrastructure",
    emoji: "🛣️", wiki: "Coastal Road (Mumbai)",
    fact: "The first part of the Mumbai Coastal Road, 10.58 km from Marine Drive to Worli, opened in stages from 11 March 2024. It includes India's first undersea road tunnel, a twin tunnel of 2.07 km under Malabar Hill and the sea. The drive that took about 40 minutes now takes about 10.",
    why: "It is the biggest new piece of land the city has made in decades, and almost all of it is for cars.",
    mech: "Mumbai's west coast had no through road, so traffic squeezed onto a few north-south streets. The BMC filled in about 111 hectares of sea to build a road along the shore, with gardens and a promenade on the new land. Under Malabar Hill it could not dig an open cut, so a giant boring machine made twin tunnels. The road joins the Bandra-Worli Sea Link at Worli. It cost about 13,000 crore rupees, among the costliest roads per km in India.",
    models: ["bottlenecks", "second-order-thinking"],
    q: "What does the Coastal Road do, and how was it built?",
    a: "It gives the west coast a through road from Marine Drive to Worli, cutting a 40-minute drive to about 10. The BMC filled in sea for most of it and bored a 2.07 km twin tunnel under Malabar Hill. The first 10.58 km opened from March 2024.",
    chain: [["No through road on the west coast", ["through road", "squeezed", "few", "no road"]], ["Built on land filled in from the sea", ["filled", "reclaim", "sea", "hectares"]], ["A 2.07 km tunnel under Malabar Hill", ["tunnel", "2.07", "malabar", "boring"]], ["Opened 2024, 40 minutes became 10", ["2024", "10 minutes", "40 minutes", "faster"]]],
    mcq: { q: "What is special about the Coastal Road's tunnel?", o: ["It is India's first undersea road tunnel", "It is the longest tunnel in Asia", "It carries trains and cars together", "It was dug by hand"] },
    bring: "When someone drives to town: “That tunnel under Malabar Hill is India's first undersea road tunnel. The whole stretch cost about 13,000 crore.”",
    follow: "Should a city spend this much on a road that mostly carries cars?",
    deeper: "The road was fought in court by Koli fishermen from Worli, who won wider gaps between the pillars so their boats could pass. The remaining stretch north from Bandra to Versova was under construction in 2026." },

  { id: "mw-sewage", type: "concept", domain: "science", title: "Where Mumbai's sewage goes", value: 4, cue: "dirty beaches, smells at low tide, or the sea at Worli",
    emoji: "🌊", wiki: "Sewage treatment",
    fact: "Mumbai produces over 2,000 million litres of sewage every day. For decades most of it got only basic screening and then went into the sea through long pipes. The Worli outfall pipe runs about 3.4 km into the sea and the Bandra pipe about 3.7 km.",
    why: "This is why the sea at Dadar and Juhu is not safe to swim in, and why new treatment plants are among the BMC's largest projects.",
    mech: "The city is divided into seven sewerage zones, each with a pumping station at the shore. Treating sewage fully needs big tanks and land, which Mumbai lacked. So engineers chose the sea as the treatment plant. Long outfall pipes carry the waste far out where the tide dilutes it and carries it away. But growth outran the pipes, and many areas still send sewage into creeks with no pipe at all. The BMC is now building seven large treatment plants to clean the water before release.",
    models: ["margin-of-safety", "second-order-thinking"],
    q: "How does Mumbai dispose of its sewage, and why is it a problem?",
    a: "Sewage from seven zones is pumped to the shore, given basic screening, and sent far out to sea through outfall pipes about 3.4 km long. The tide dilutes it. But the city grew faster than the system, so beaches and creeks are dirty, and seven new treatment plants are being built.",
    chain: [["Over 2,000 million litres a day in seven zones", ["2,000", "million litres", "seven zones", "zone"]], ["Mostly basic screening only", ["screen", "basic", "no treatment", "untreated", "not treated"]], ["Long pipes carry it far out to sea", ["pipe", "outfall", "3.4", "sea", "far out"]], ["Growth outran it; new plants being built", ["outran", "grew faster", "new plant", "treatment plant", "seven"]]],
    mcq: { q: "How did Mumbai mainly dispose of its sewage for decades?", o: ["Through long pipes far out into the sea after basic screening", "By burning it in incinerators", "By full treatment and reuse in farms", "By trucking it to Deonar"] },
    bring: "At Juhu beach: “There is a sewage pipe running over 3 km into this sea. The tide is doing the cleaning.”",
    follow: "If treatment plants need so much land, where in Mumbai would you put them?",
    deeper: "The new plants at Worli, Bandra, Dharavi, Versova, Malad, Bhandup and Ghatkopar together are planned to treat over 2,400 million litres a day, and the contracts were worth over 25,000 crore rupees." },

  { id: "mw-deonar", type: "event", domain: "science", title: "Deonar: a century of garbage and the 2016 fire", value: 4, cue: "garbage, smoke over the eastern suburbs, or waste",
    emoji: "🔥", wiki: "Deonar dumping ground",
    fact: "Mumbai began dumping its waste at Deonar in 1927. The ground now covers about 132 hectares and in places is taller than a ten-storey building. In January 2016 a fire burned there for days. Smoke was photographed from satellites and 74 schools were shut.",
    why: "A city of over a crore people has had almost nowhere to put its waste. The fire made a hidden system visible from space.",
    mech: "Mumbai sends thousands of tonnes of mixed waste a day to a few grounds. At Deonar the rubbish was piled up for 90 years with little processing. Buried organic waste rots without air and makes methane gas. In the dry heat of January the gas and dry waste caught fire. Once lit, a landfill fire smoulders deep inside and is very hard to put out. Winds carried the smoke over Chembur, Govandi and Mankhurd for days.",
    models: ["second-order-thinking", "margin-of-safety"],
    q: "Why did the Deonar dump burn for days in 2016?",
    a: "Deonar has taken Mumbai's waste since 1927 with little processing. Rotting waste makes methane, which caught fire in the dry heat. A landfill fire burns deep inside and is hard to put out, so smoke covered the area for days and 74 schools closed.",
    chain: [["Dumping since 1927 on 132 hectares", ["1927", "132", "hectare", "oldest"]], ["Rotting waste makes methane", ["methane", "gas", "rot"]], ["Fire burns deep and is hard to put out", ["deep", "smoulder", "hard to put out", "days"]], ["Smoke seen from satellites; 74 schools shut", ["satellite", "74", "school", "smoke"]]],
    mcq: { q: "Since when has Mumbai dumped waste at Deonar?", o: ["1927", "1977", "1997", "2007"] },
    bring: "When the smell at Chembur comes up: “Deonar has taken the city's garbage since 1927. In 2016 its fire was photographed from space.”",
    follow: "What would it take for your building to send out half the waste it does now?",
    deeper: "The BMC's other main ground is at Kanjurmarg. A waste-to-energy plant at Deonar was planned to burn 600 tonnes a day, and the Dharavi redevelopment plan has also asked for part of the Deonar land." },

  { id: "mw-flamingos", type: "scientific principle", domain: "science", title: "Why flamingos come to Thane creek", value: 4, cue: "flamingos, Sewri, or birds in the city",
    emoji: "🦩", wiki: "Thane Creek Flamingo Sanctuary",
    fact: "Every winter over a lakh flamingos arrive at Thane creek. A count in 2022 found more than 1.3 lakh birds. Thane Creek Flamingo Sanctuary was declared in August 2015. A strange reason brings them here: the city's dirty water.",
    why: "Pink birds in the shadow of a chemical factory are the city's most beautiful side effect.",
    mech: "Flamingos eat tiny blue-green algae and small creatures from the mud. Sewage flowing into Thane creek is full of nutrients. The nutrients feed the algae, so the mudflats are covered with food. The creek is also shallow and sheltered, with mangroves around it. Most of the birds breed in the Rann of Kutch in Gujarat and come south when the Rann dries. As the city grew from the 1980s and sewage increased, the flocks grew too.",
    models: ["second-order-thinking", "feedback-loops"],
    q: "Why do so many flamingos come to Thane creek every winter?",
    a: "Sewage flowing into the creek carries nutrients that feed blue-green algae, the flamingos' food. The shallow, sheltered mudflats hold this food in large amounts. The birds breed in the Rann of Kutch and fly here when it dries. Counts have passed 1.3 lakh birds.",
    chain: [["Flamingos eat blue-green algae from the mud", ["algae", "mud", "eat", "food"]], ["Sewage nutrients make the algae grow", ["sewage", "nutrient", "dirty"]], ["They breed in Kutch and come when it dries", ["kutch", "rann", "breed", "dries"]], ["Over a lakh birds; sanctuary in 2015", ["lakh", "1.3", "130,000", "2015", "sanctuary"]]],
    mcq: { q: "What feeds the algae that flamingos eat in Thane creek?", o: ["Nutrients from the city's sewage", "Fish food thrown by tourists", "Salt from the salt pans", "Oil from passing ships"] },
    bring: "When someone sees flamingos at Sewri: “They are here because of our sewage. It feeds the algae they eat.”",
    follow: "Would the flamingos leave if we cleaned the creek completely?",
    deeper: "Both greater and lesser flamingos come. The lesser flamingo eats almost only algae and is the pinker one. The Atal Setu bridge was routed and designed partly to disturb these birds as little as possible." },

  { id: "mw-mangroves", type: "concept", domain: "science", title: "Mangroves: the city's free sea wall", value: 4, cue: "flooding, coastal building, or green patches near creeks",
    emoji: "🌿", wiki: "Mangrove",
    fact: "In October 2005 the Bombay High Court banned the cutting of mangroves and construction within 50 metres of them. Mumbai's mangrove cover rose from about 42 square km in 2005 to about 66 square km by 2017. The state set up a special Mangrove Cell in 2012, the only one of its kind in India.",
    why: "Mangroves are the cheapest flood defence the city has, and they were being filled in for buildings until a court stopped it.",
    mech: "Mangroves are trees that grow in salt water along creeks. Their tangled roots trap mud, slow waves, and hold the shore together. They also soak up storm surge like a sponge. For decades builders filled in mangrove land because it was flat, empty and near the city. The great flood of July 2005 showed what happens when the sponge is gone. The High Court order came three months later. Satellite maps now check for new cutting.",
    models: ["margin-of-safety", "second-order-thinking"],
    q: "Why does Mumbai protect its mangroves so strictly?",
    a: "Mangrove roots slow waves, trap mud and soak up storm water, so they are a free sea wall. Builders filled them in for years. After the 2005 flood, the Bombay High Court banned cutting them and building within 50 metres, and cover grew from about 42 to 66 square km.",
    chain: [["Mangrove roots slow waves and soak up water", ["root", "wave", "soak", "sponge", "sea wall"]], ["Builders filled them in for land", ["fill", "builder", "construct", "cut"]], ["High Court ban in 2005, 50-metre buffer", ["high court", "2005", "ban", "50 metre", "50 m"]], ["Cover rose from 42 to 66 square km", ["42", "66", "square km", "grew", "rose"]]],
    mcq: { q: "What did the Bombay High Court order in 2005 about mangroves?", o: ["No cutting, and no building within 50 metres of them", "All mangroves to be replaced with concrete walls", "Mangroves may be cut if replanted elsewhere", "Mangroves to be cut to reduce mosquitoes"] },
    bring: "When flooding comes up: “Mangroves are the city's free sea wall. A court had to step in before we stopped cutting them.”",
    follow: "Have you noticed the mangroves along the Sion-Panvel highway or the Western Express Highway?",
    deeper: "Mangroves also store far more carbon per hectare than most forests. Fishing communities use them as nurseries, because young fish and crabs hide among the roots." },

  { id: "mw-marathon", type: "business concept", domain: "business", title: "The Mumbai Marathon as a charity machine", value: 3, cue: "running, charity, or January in the city",
    emoji: "🏃", wiki: "Mumbai Marathon",
    fact: "The Mumbai Marathon began in 2004 and is Asia's largest marathon. The 2026 edition had over 69,000 participants. Runners and companies raised over 60 crore rupees for about 309 NGOs that year, taking the total since 2004 past 500 crore.",
    why: "A road race became one of the biggest fund-raising events in India. The design of the event, not the running, did it.",
    mech: "Places in the race are limited and in demand. So the organisers set aside charity places. A runner gets a place by promising to raise a minimum sum for an approved NGO. Friends and colleagues give because they know the person and the date. Companies send teams and match what their staff raise. Every year the number of fundraisers grows, and the money follows. The city gets a festival and the NGOs get a yearly income.",
    models: ["incentives", "reciprocity", "social-proof"],
    q: "How does the Mumbai Marathon raise so much money for charity?",
    a: "Race places are scarce, so charity places are given to runners who promise to raise money for an NGO. Friends give because they know the runner, and companies match staff donations. In 2026 over 60 crore rupees was raised, and more than 500 crore since 2004.",
    chain: [["Began 2004, Asia's largest", ["2004", "largest", "asia"]], ["Scarce places given for charity pledges", ["scarce", "limited", "charity place", "promise", "pledge", "set aside"]], ["Friends give, companies match", ["friend", "match", "colleague", "team"]], ["Over 60 crore in 2026, 500 crore in total", ["60 crore", "500 crore", "309", "ngo"]]],
    mcq: { q: "How did the Mumbai Marathon raise over 500 crore rupees for charity since 2004?", o: ["Runners pledge to raise money for NGOs to get a place", "Ticket sales to spectators", "A tax on the city's gyms", "Prize money given back by winners"] },
    bring: "When someone trains for the marathon: “Most of the money it raises comes from ordinary runners asking friends. Over 500 crore so far.”",
    follow: "Would you give more to a cause, or to a friend who is running for it?",
    deeper: "The race is run by Procam International, with the title sponsor Tata since 2018. The charity side is managed by United Way Mumbai. In 2026, 13 individual runners each raised over 1 crore rupees." },

  { id: "mw-rent-control", type: "concept", domain: "economics", title: "The 1947 rent freeze and the pagdi system", value: 5, cue: "high rents, crumbling buildings, or why South Mumbai looks old",
    emoji: "🏚️", wiki: "Rent control in India",
    fact: "The Bombay Rent Act of 1947 froze rents at their level of September 1940. Many families in old South Mumbai buildings still pay a few hundred rupees a month. About 19,000 old buildings in Mumbai are still under this system.",
    why: "A law meant to protect tenants after the war ended up freezing a whole city in time. It explains both the collapsing buildings and the sky-high rents elsewhere.",
    mech: "The freeze meant a landlord earned almost nothing, so he stopped repairing the building. The tenant could not be evicted and could pass the flat to children. Since the rent was worthless, the right to occupy became the valuable thing. A new tenant paid a large lump sum, called pagdi, split between the old tenant and the landlord. Builders stopped making flats for rent, so new housing was only for sale. Less rental supply pushed up rents in the free market.",
    models: ["incentives", "second-order-thinking", "goodharts-law"],
    q: "How did the 1947 rent freeze shape Mumbai's housing?",
    a: "Rents were frozen at 1940 levels, so landlords earned nothing and stopped repairs. Tenants could not be evicted, so the right to occupy became valuable and was sold for a lump sum called pagdi. Builders stopped building for rent, which made free-market rents very high.",
    chain: [["Rents frozen at 1940 levels", ["1940", "frozen", "froze", "freeze", "1947"]], ["Landlords stopped repairs", ["repair", "earned nothing", "landlord", "crumbl"]], ["The right to occupy was sold as pagdi", ["pagdi", "lump sum", "occupy", "right"]], ["No new rental housing, so free rents soared", ["rental", "for rent", "supply", "soar", "very high", "sky-high"]]],
    mcq: { q: "What is pagdi in Mumbai housing?", o: ["A lump sum paid to take over a rent-controlled flat", "A yearly tax on old buildings", "A deposit returned when a tenant leaves", "A government subsidy for repairs"] },
    bring: "When rents come up: “Some families in Fort still pay 1940 rents. That same law is why the rest of us pay so much.”",
    follow: "Who do you think gains most from rent control today, the poor or the lucky?",
    deeper: "A repair cess was added in 1969 so the state could patch these buildings. The Maharashtra Rent Control Act of 1999 replaced the old law but kept protection for existing tenants, allowing only 4 percent yearly increases." },

  { id: "mw-fsi", type: "concept", domain: "economics", title: "FSI: the number that shapes Mumbai's skyline", value: 5, cue: "tall towers, builders, or why old areas are low",
    emoji: "📐", wiki: "Floor area ratio",
    fact: "FSI, the floor space index, is the total floor area a builder may build divided by the plot area. An FSI of 1 on a 1,000 square metre plot allows 1,000 square metres of floors. For decades Mumbai's island city had a base FSI of only 1.33. The 2034 development plan raised it to 3 for homes.",
    why: "This one number decides how much housing a city can have. Keeping it low in a city with no spare land is a main reason homes cost so much.",
    mech: "A low FSI limits how many floors fit on a plot. Mumbai set 1.33 in 1964 and later cut it further in 1991, hoping to limit crowding. But people kept coming, so the same land had to hold more families in less legal space. That pushed people into slums and pushed prices up. The government then sold extra FSI as a premium and gave bonus FSI for slum and old-building projects. Builders chase these bonuses, which is why towers rise next to chawls.",
    models: ["bottlenecks", "incentives", "second-order-thinking"],
    q: "What is FSI and why does it matter so much in Mumbai?",
    a: "FSI is the floor area allowed divided by the plot area. Mumbai kept the island city at 1.33 for decades to limit crowding, but people kept coming, so legal space ran short and prices rose. Extra FSI is now sold as a premium or given as a bonus, which is what builders chase.",
    chain: [["FSI is floor area divided by plot area", ["divided", "floor area", "plot", "ratio"]], ["Island city kept at 1.33 for decades", ["1.33", "low", "decades", "1964", "1991"]], ["People kept coming, so prices rose", ["kept coming", "ran short", "prices", "slum", "crowd"]], ["Extra FSI sold or given as bonus", ["premium", "bonus", "extra", "sold", "tdr"]]],
    mcq: { q: "A plot of 1,000 square metres with FSI 2 allows how much floor area?", o: ["2,000 square metres", "500 square metres", "1,000 square metres", "200 square metres"] },
    bring: "When tower prices come up: “Everything in Mumbai real estate is about FSI. The island city was stuck at 1.33 for decades.”",
    follow: "Would you rather have more floors and more people, or lower buildings and higher prices?",
    deeper: "Mumbai's FSI is very low by world standards. Central Manhattan and Hong Kong allow 10 or more. Mumbai also has a 35 percent fungible FSI for balconies and lobbies, which builders often sell as flat area." },

  { id: "mw-sra", type: "business concept", domain: "business", title: "SRA: how slum towers get built for free", value: 4, cue: "slum redevelopment, builders, or a new tower next to huts",
    emoji: "🏗️", wiki: "Slum Rehabilitation Authority",
    fact: "Under the Slum Rehabilitation Scheme of 1995, a builder gives each eligible slum family a free flat of 300 square feet. In return the builder gets extra building rights to construct flats for sale on the same land. No government money is needed.",
    why: "It is a trade: free homes for the poor, paid for by the rich buying towers above them. It also explains much of what is going up around you.",
    mech: "Slum land in Mumbai is valuable but occupied. The state cannot pay to rehouse lakhs of families. So the SRA offers builders a deal. If 70 percent of a slum's families agree, the builder rehouses them in new towers on part of the plot. The builder then gets FSI worth more than what he gave, and can sell the extra flats at market price. Rights he cannot use on the plot can be sold to other builders as TDR. Profit comes from the free sale part. Delays, disputes and poor upkeep are common.",
    models: ["incentives", "game-theory"],
    q: "How does a slum rehabilitation project pay for itself?",
    a: "If enough slum families agree, a builder gives each one a free 300 square foot flat on part of the land. In return he gets extra FSI, builds flats for sale on the rest, and can sell unused rights as TDR. The sale flats pay for the free ones.",
    chain: [["Free 300 sq ft flats for eligible families", ["300", "free flat", "free", "rehouse"]], ["Needs 70 percent of families to agree", ["70", "agree", "consent"]], ["Builder gets extra FSI to sell", ["extra fsi", "fsi", "sale", "sell", "market"]], ["Unused rights sold as TDR", ["tdr", "transfer", "other builders"]]],
    mcq: { q: "Who pays for the free flats in an SRA project?", o: ["Buyers of the builder's flats for sale on the same land", "The central government", "The slum families through EMIs", "The BMC from property tax"] },
    bring: "When a new tower rises next to a slum: “That is an SRA scheme. The buyers upstairs are paying for the free flats downstairs.”",
    follow: "Would you buy a flat in the sale wing of an SRA building?",
    deeper: "Only structures that existed on 1 January 2000, and later 2011 with payment, are eligible. The free flat size was raised from 225 to 269 to 300 square feet over the years. The Dharavi project is the largest such scheme ever attempted." },

  { id: "mw-chawls", type: "concept", domain: "design", title: "The chawl: one room, one corridor, one city", value: 4, cue: "old buildings, Lalbaug, Girgaon, or community life",
    emoji: "🏘️", wiki: "Chawl",
    fact: "A chawl is a building of single rooms, about 10 by 12 feet each, opening onto a long shared corridor, with common toilets at the end. Thousands were built from the 1860s onwards for mill workers. The BDD chawls at Worli and elsewhere, 207 buildings in all, were built by the government between 1920 and 1925.",
    why: "The chawl made Mumbai's working class and its culture. Ganeshotsav, theatre groups and trade unions all grew in its corridors.",
    mech: "Mill workers were single men from the Konkan who came to earn and send money home. They needed a cheap bed near the mill, not a home. So owners built rooms with no kitchen or toilet, stacked along a corridor to fit the most people per square foot. One room often held ten men sleeping in shifts. Later, families moved in and the corridor became a shared living room. After the 1896 plague, the city's Improvement Trust built better chawls with light and air.",
    models: ["first-principles", "network-effects"],
    q: "Why were chawls built the way they were?",
    a: "Mill workers were single men who needed a cheap bed near the mill. So owners built single rooms along a shared corridor with common toilets, fitting the most people per square foot. Families later moved in and the corridor became a shared space that built the city's working-class culture.",
    chain: [["Single rooms along a shared corridor", ["corridor", "single room", "one room", "10 by 12"]], ["Built for single mill workers", ["mill", "single men", "worker", "konkan"]], ["Common toilets, maximum people per square foot", ["common toilet", "shared toilet", "square foot", "cheap"]], ["Families moved in; a shared culture grew", ["famil", "culture", "ganesh", "union", "living room"]]],
    mcq: { q: "What is the typical design of a chawl?", o: ["Single rooms along a shared corridor with common toilets", "Two-bedroom flats around a lift", "Bungalows around a garden", "Shops below and one large hall above"] },
    bring: "When Lalbaug comes up: “The chawl corridor was the city's first living room. Ganeshotsav and the unions both started there.”",
    follow: "Did your family ever live in a chawl? What do they remember?",
    deeper: "The BDD chawl rooms were about 160 square feet. Their redevelopment, started in 2021, gives each family a 500 square foot flat. Many chawls in Girgaon are 150 years old and still lived in." },

  { id: "mw-housing-society", type: "concept", domain: "business", title: "You do not own your flat, your society does", value: 4, cue: "society meetings, maintenance bills, or buying a flat",
    emoji: "📜", wiki: "Housing cooperative",
    fact: "Most Mumbai flats are held through a cooperative housing society, under the Maharashtra Co-operative Societies Act of 1960. Legally the society owns the land and the building. A flat owner owns shares in the society, shown by a share certificate, which give the right to occupy one flat.",
    why: "This is why the society can fine you, why redevelopment needs a vote, and why a share certificate matters as much as the sale agreement.",
    mech: "When a builder finishes a building, the buyers form a society and the builder is meant to transfer the land to it by conveyance. Each buyer gets shares, usually five of 50 rupees each. The society collects maintenance, repairs the building and keeps the records. Because the society owns everything, decisions are taken by majority vote at the general body. For redevelopment, a large majority of members must agree. Many builders never did the conveyance, so the state created deemed conveyance to force it.",
    models: ["game-theory", "incentives"],
    q: "Who legally owns a flat in a Mumbai housing society, and why does it matter?",
    a: "The cooperative society owns the land and building. The flat owner holds shares in the society, shown by a share certificate, which give the right to occupy. So decisions like redevelopment need a majority vote, and conveyance from the builder to the society matters.",
    chain: [["The society owns land and building", ["society owns", "owns the land", "owns everything", "legally"]], ["A member holds shares and a certificate", ["share", "certificate"]], ["Decisions by majority vote", ["vote", "majority", "general body"]], ["Conveyance from builder to society", ["conveyance", "transfer", "builder"]]],
    mcq: { q: "In a Mumbai cooperative housing society, what does a flat buyer legally hold?", o: ["Shares in the society that give the right to occupy a flat", "Direct title to the land under the flat", "A lease from the BMC", "A licence from the builder"] },
    bring: "When maintenance bills come up: “On paper the society owns your flat. You own shares in the society. That is why the general body can decide so much.”",
    follow: "Has your society received its conveyance from the builder?",
    deeper: "Mumbai has tens of thousands of registered housing societies. Under the Maharashtra Ownership Flats Act of 1963, the builder must convey the land within four months of the society being formed, a rule widely broken." },

  { id: "mw-hawkers", type: "concept", domain: "economics", title: "Hawkers: the shop with no rent", value: 4, cue: "footpaths, street food, or BMC drives",
    emoji: "🛒", wiki: "Street Vendors Act, 2014",
    fact: "Mumbai has only about 16,000 licensed hawkers, but a BMC survey after the Street Vendors Act of 2014 counted about 99,000 vendors. Unions estimate the true number at over 2.5 lakh. The Act says a city should allow hawkers up to 2.5 percent of its population.",
    why: "Hawkers sell the cheapest food and goods in a city of very costly shops. The fight over footpaths is really a fight over who may use public land to earn.",
    mech: "A shop in Mumbai pays huge rent. A hawker pays none, so he can sell a vada pav for 15 rupees. Shopkeepers and walkers complain about blocked footpaths. The BMC stopped giving licences decades ago, so most hawkers are illegal and pay bribes instead of fees. The 2014 Act tried to fix this with a survey, vending zones and a Town Vending Committee with hawkers on it. Mumbai's committee and zones have taken over a decade to set up, and court orders keep pushing the BMC.",
    models: ["incentives", "game-theory"],
    q: "Why does Mumbai have so many unlicensed hawkers, and what did the 2014 Act try to do?",
    a: "Hawkers pay no rent so they can sell cheaply, but the BMC stopped issuing licences decades ago, so most are unlicensed and pay bribes. The Street Vendors Act of 2014 ordered a survey, vending zones and a committee, and allows hawkers up to 2.5 percent of the population. Mumbai has been slow to apply it.",
    chain: [["No rent, so very cheap goods", ["no rent", "rent", "cheap"]], ["Licences stopped, so most are illegal", ["licence", "license", "illegal", "bribe", "16,000"]], ["2014 Act: survey, zones and committee", ["2014", "survey", "zone", "committee"]], ["Up to 2.5 percent of the population", ["2.5", "percent", "population"]]],
    mcq: { q: "What did the Street Vendors Act of 2014 require cities to do?", o: ["Survey vendors, create vending zones and a Town Vending Committee", "Ban all street vending near stations", "Give every vendor a free shop", "Hand vending to private companies"] },
    bring: "When a BMC drive clears a footpath: “The 2014 law says hawkers can be 2.5 percent of the city. Mumbai still has not finished setting up the zones.”",
    follow: "Would you pay more for your evening snack to have a clear footpath?",
    deeper: "A famous 1985 Supreme Court case, Olga Tellis, held that pavement dwellers' right to life includes the right to earn a living, which shaped later hawker law." },

  { id: "mw-sassoon-dock", type: "business concept", domain: "business", title: "Sassoon Dock: the fish auction at dawn", value: 3, cue: "fish, Colaba, or the Koli community",
    emoji: "🐟", wiki: "Sassoon Docks",
    fact: "Sassoon Dock in Colaba was built in 1875 by the Sassoon family, Baghdadi Jewish traders. It was Bombay's first wet dock, a basin that keeps water in at low tide. Today over a thousand boats land their catch there and the fish are sold by auction before sunrise.",
    why: "Much of the fish on Mumbai's plates passes through one small dock, in a few noisy hours, before most of the city wakes.",
    mech: "Fishing boats return at night. Fish spoils fast in the heat, so it must be sold and moved before the sun gets hot. The auction lets many buyers bid at once, so the price is set in seconds. Koli women, whose families have fished here for centuries, buy lots and carry them to markets across the city on the first trains. Ice, trucks and dryers for bombil work around the dock. By 8 am the day's trade is over.",
    models: ["bottlenecks", "incentives"],
    q: "Why does the fish trade at Sassoon Dock happen before dawn?",
    a: "Boats return at night and fish spoils fast in heat, so it must be sold quickly. An auction sets prices in seconds, and Koli women carry the fish to markets across the city on the first trains. The dock, built in 1875, was Bombay's first wet dock.",
    chain: [["Built in 1875 as the first wet dock", ["1875", "wet dock", "sassoon"]], ["Fish spoils fast, so sell before the heat", ["spoil", "heat", "fast", "before"]], ["Auction sets the price in seconds", ["auction", "bid", "price"]], ["Koli women carry it to markets by train", ["koli", "women", "market", "train"]]],
    mcq: { q: "What was Sassoon Dock when it was built in 1875?", o: ["Bombay's first wet dock, built by the Sassoon family", "A naval base for the British fleet", "A passenger terminal for ships to England", "A shipyard for building steamers"] },
    bring: "When fish prices come up: “Go to Sassoon Dock at 5 am. The whole city's fish price is set there by shouting.”",
    follow: "Have you ever seen a live auction? What did you notice about how prices moved?",
    deeper: "The Sassoons also built the Sassoon Library and the David Sassoon Hospital in Pune. Fish catches along Mumbai's coast have fallen, and many boats now go far out for several days." },

  { id: "mw-apmc-vashi", type: "business concept", domain: "business", title: "APMC Vashi: the city's wholesale kitchen", value: 4, cue: "vegetable prices, onions, or why things cost what they cost",
    emoji: "🧅", wiki: "Agricultural produce market committee",
    fact: "Most fruit, vegetables, grain and spices sold in Mumbai first pass through the APMC market at Vashi in Navi Mumbai. The state moved the wholesale trade there from the old city in stages, with the fruit market shifting from Crawford Market in 1996. It is among the largest wholesale markets in Asia.",
    why: "The price of onions in your lane is set here at 4 am, by traders you will never meet.",
    mech: "Trucks from across India arrive at night. Farmers or their agents sell to licensed commission agents, who sell to wholesalers, who sell to the retailers who come before dawn. Each step adds a margin, often 10 to 20 percent. The market was moved out of Mumbai because hundreds of trucks a day were jamming the island city. Vashi had space and highway access. Moving the market also pulled thousands of jobs across the harbour and helped Navi Mumbai grow.",
    models: ["bottlenecks", "network-effects"],
    q: "How does food reach Mumbai's shops, and why is the wholesale market in Vashi?",
    a: "Trucks bring produce to APMC Vashi at night, where farmers sell to agents, agents to wholesalers, and wholesalers to retailers before dawn, each adding a margin. The market was moved from Crawford Market and Byculla to Vashi because trucks jammed the old city and Vashi had space.",
    chain: [["Trucks arrive at night from across India", ["truck", "night", "across india", "arrive"]], ["Farmer, agent, wholesaler, retailer", ["agent", "wholesal", "retail", "margin"]], ["Moved from Crawford Market to Vashi", ["crawford", "vashi", "moved", "1996"]], ["Because trucks jammed the old city", ["jam", "old city", "space", "highway"]]],
    mcq: { q: "Why was Mumbai's wholesale produce market moved to Vashi?", o: ["Trucks were jamming the old city and Vashi had space", "The old market burned down", "Farmers refused to enter Mumbai", "Vashi had the only cold storage in the region"] },
    bring: "When onion prices jump: “Every onion in Mumbai went through Vashi at 4 am. Three middlemen touched it before your bhajiwala.”",
    follow: "How many hands do you think your vegetables pass through before you?",
    deeper: "Crawford Market, opened in 1869 and now named after Mahatma Jyotiba Phule, is still a retail market. APMC Vashi has five separate markets: onion and potato, fruit, vegetables, grain, and spices." },

  { id: "mw-islanding", type: "historical story", domain: "science", title: "Islanding: the switch that keeps Mumbai lit", value: 5, cue: "power cuts, the grid, or 12 October 2020", story: "blackout2020",
    emoji: "💡", wiki: "Tata Power",
    fact: "Mumbai rarely has power cuts because of a system called islanding, set up by Tata Power in 1981. When the state grid fails, Mumbai cuts itself off and runs on its own plants. Tata Power says it saved the city 27 times. On 12 October 2020 it failed, and the city went dark for hours.",
    why: "A city that cannot stop needs a safety switch. Mumbai has had one for 40 years, and most people never knew.",
    mech: "Mumbai's power comes from Tata's hydro plants in the Western Ghats, started at Khopoli in 1915, from the Trombay plant, and from the state grid. If the grid collapses, a healthy city connected to it would be dragged down too. So relays sense the fault and cut Mumbai off within a fraction of a second. The island must then balance its own supply and demand instantly. In 2020 two state substations tripped at once. Mumbai islanded, but the sudden loss of about 1,000 MW was too big to balance, and the island collapsed too.",
    models: ["margin-of-safety", "bottlenecks"],
    q: "What is islanding, and why did it fail in 2020?",
    a: "When the state grid fails, relays cut Mumbai off within a fraction of a second so it runs on its own plants, like Khopoli hydro and Trombay. Set up in 1981, it saved the city many times. In October 2020 a sudden loss of about 1,000 MW was too big to balance, so Mumbai's island collapsed too.",
    chain: [["Mumbai has its own plants: Khopoli hydro, Trombay", ["khopoli", "trombay", "own plant", "hydro", "1915"]], ["Relays cut the city off when the grid fails", ["cut", "relay", "island", "separate", "fraction"]], ["Set up 1981; saved the city many times", ["1981", "27", "saved", "many times"]], ["Failed in October 2020 under a 1,000 MW shock", ["2020", "1,000 mw", "collapse", "fail", "too big"]]],
    mcq: { q: "What does Mumbai's islanding system do?", o: ["Cuts the city off from a failing grid so it runs on its own plants", "Stores power in batteries on an island", "Imports power from Gujarat by sea cable", "Shuts off power to the suburbs first"] },
    bring: "When the lights stay on during a storm: “Mumbai has a switch that cuts it off from the grid when the state fails. It is called islanding, since 1981.”",
    follow: "What other systems in your life have a safety switch you have never seen work?",
    deeper: "Tata's first hydro plant at Khopoli opened in 1915 to power the cotton mills with water from lakes near Lonavala. Its sister plants at Bhivpuri and Bhira followed. BEST, Adani and Tata still share Mumbai's power supply." },

  { id: "mw-gpo-pincode", type: "fact", domain: "history", title: "The GPO and the six digits of a PIN code", value: 3, cue: "addresses, courier delays, or the big dome near CST",
    emoji: "📮", wiki: "General Post Office, Mumbai",
    fact: "Mumbai's General Post Office near CST was finished in 1913. Its dome is modelled on the Gol Gumbaz of Bijapur and is among the largest in India. Its PIN code, 400001, is the first in Mumbai. The PIN system itself began on 15 August 1972.",
    why: "Six digits sort hundreds of crores of letters a year. The code was designed so that a sorter who cannot read the address can still send the letter the right way.",
    mech: "India has many languages and scripts, and addresses were often unclear. Shriram Bhikaji Velankar of the Posts department designed a number code. The first digit gives the region, the first two the sub-region, the first three the sorting district, and the last three the delivery post office. So 4 means western India, 400 means Mumbai, and 400001 means the GPO. A sorter only reads the digits. Letters move from region to district to office, each step narrowing the search.",
    models: ["first-principles", "bottlenecks"],
    q: "How does a PIN code work, and what does Mumbai's 400001 mean?",
    a: "The first digit is the region, the first three the sorting district, and the last three the delivery post office. So 4 is western India, 400 is Mumbai and 400001 is the GPO near CST. Letters are sorted step by step without reading the address. The system began in 1972.",
    chain: [["GPO built 1913 with a Gol Gumbaz dome", ["1913", "gol gumbaz", "dome", "gpo"]], ["PIN code began 15 August 1972", ["1972", "velankar", "began"]], ["Digits narrow from region to post office", ["region", "district", "post office", "narrow", "first digit", "first three"]], ["400001 is the Mumbai GPO", ["400001", "400", "mumbai"]]],
    mcq: { q: "What does the first digit of an Indian PIN code tell you?", o: ["The postal region of the country", "The street number", "The year the post office opened", "The type of mail"] },
    bring: "When someone asks for your PIN: “The 4 means west India, 400 means Mumbai. The GPO near CST is 400001.”",
    follow: "Do you know what your own PIN code's digits stand for?",
    deeper: "The GPO was designed by John Begg in the Indo-Saracenic style and took nine years to build. Bombay's first post office dates from 1794." },

  { id: "mw-26-11", type: "historical story", domain: "history", title: "26/11 and the staff of the Taj", value: 5, cue: "the Taj hotel, courage, or 26 November", story: "taj2008",
    emoji: "🕯️", wiki: "2008 Mumbai attacks",
    fact: "On 26 November 2008 ten gunmen attacked Mumbai at several places, including CST station, the Taj Mahal Palace hotel, the Oberoi Trident, Leopold Cafe and Nariman House. The siege lasted nearly 60 hours. 166 people were killed. At the Taj, staff stayed to protect guests, and several died doing so.",
    why: "It was the darkest night in the city's recent history. The way ordinary hotel workers behaved became a lesson studied around the world.",
    mech: "The attackers came by sea in a small boat and split into pairs. Police at CST and elsewhere faced automatic rifles with old weapons. At the Taj, hundreds of guests were inside. Staff knew the building and its back passages. They formed human chains, led guests to safer halls, and stood between guests and the doors. Telephone operators stayed at their desks calling rooms. The hotel's general manager, Karambir Kang, kept working even after losing his wife and sons in the fire upstairs. Commandos ended the siege on 29 November.",
    models: ["commitment-consistency", "incentives"],
    q: "What happened on 26 November 2008, and why is the Taj staff remembered?",
    a: "Ten gunmen attacked several places in Mumbai, including CST and the Taj hotel, and 166 people were killed in a siege of nearly 60 hours. Taj staff knew the building, led guests to safety through back passages, and shielded them, and several staff died doing so.",
    chain: [["Ten gunmen attacked several places on 26 November 2008", ["ten", "26 november", "2008", "cst", "several places"]], ["166 killed in a siege of nearly 60 hours", ["166", "60 hours", "siege", "three days"]], ["Taj staff stayed and led guests to safety", ["staff", "stayed", "led guests", "shield", "human chain"]], ["Several staff died protecting guests", ["died", "lives", "sacrific"]]],
    mcq: { q: "How many people were killed in the 26/11 attacks?", o: ["166", "26", "1,000", "12"] },
    bring: "When 26/11 comes up: “The Taj staff had exits and did not use them. They stayed between the guests and the gunmen.”",
    follow: "What makes someone stay at their post when they could leave?",
    deeper: "Harvard Business School made a case study on why the Taj staff behaved as they did, pointing to how the hotel hired and trained for character. The attacks led to the National Investigation Agency and the posting of NSG commandos in Mumbai." },

  { id: "mw-aarey-dairy", type: "fact", domain: "history", title: "Aarey: a dairy built to move cattle out of the city", value: 3, cue: "milk, Aarey, or the green patch near Goregaon",
    emoji: "🥛", wiki: "Aarey Milk Colony",
    fact: "Aarey Milk Colony was set up in 1949 on about 1,300 hectares of forest near Goregaon. The idea came from Dara Khurody, Bombay's milk commissioner. It moved over 20,000 buffaloes out of crowded city stables into clean farms, and sent pasteurised milk back by road.",
    why: "The green lung that people now fight to protect exists because of a milk problem 75 years ago.",
    mech: "In the 1940s Bombay's milk came from buffaloes kept in filthy stables inside the city. Milk was watered down and often unsafe. Khurody's plan moved the animals to one large colony with 32 cattle farms, a central dairy, and a pipeline of clean milk to the city. The state controlled quality and price. The scheme fed over 15 lakh people and became a model for India's dairy work. Khurody shared the 1963 Ramon Magsaysay award with Verghese Kurien of Amul.",
    models: ["first-principles", "second-order-thinking"],
    q: "Why was Aarey Milk Colony created in 1949?",
    a: "Bombay's milk came from dirty stables inside the city and was often unsafe. Dara Khurody moved over 20,000 buffaloes to one large colony at Aarey with farms and a central dairy, so the state could control quality and price. It later became the green area that people now protect.",
    chain: [["City milk came from dirty stables", ["stable", "filthy", "dirty", "unsafe", "watered"]], ["Set up in 1949 by Dara Khurody", ["1949", "khurody"]], ["Buffaloes moved to farms at Aarey", ["buffalo", "cattle", "20,000", "moved", "farm"]], ["Clean milk at controlled quality and price", ["clean", "pasteur", "quality", "price", "central dairy"]]],
    mcq: { q: "What was the main purpose of Aarey Milk Colony?", o: ["To move cattle out of the city and supply clean milk", "To grow fodder for export", "To create a national park", "To house mill workers"] },
    bring: "When Aarey comes up: “Aarey exists because Bombay's milk was dirty. They moved 20,000 buffaloes there in 1949.”",
    follow: "Should Aarey stay a dairy, become a forest, or be built on?",
    deeper: "Prime Minister Nehru planted a tree at Aarey in 1951. Today Aarey holds farms, tribal hamlets, film studios, a metro depot, and leopards that wander in from the national park next door." },

  { id: "mw-best-buses", type: "concept", domain: "economics", title: "Why BEST has fewer buses than before", value: 4, cue: "waiting for a bus, BEST, or public transport money",
    emoji: "🚌", wiki: "Brihanmumbai Electric Supply and Transport",
    fact: "BEST ran about 4,500 buses a decade ago. By 2025 it had about 2,800, most of them hired from private operators on wet lease. Yet it still carries around 30 lakh passengers a day.",
    why: "Buses carry more Mumbaikars than the metro, but the system has been shrinking while the city grew.",
    mech: "BEST's bus side has lost money for years, because fares are kept low and many routes run half empty in traffic. Its electricity business used to cover the loss, but that was separated. With less money, old buses were scrapped and not replaced. BEST then hired buses with drivers from private firms, called wet lease, which is cheaper per km but has brought strikes and quality problems. In 2019 it cut the minimum fare to 5 rupees and ridership jumped, which shows that demand is there if the buses are.",
    models: ["incentives", "feedback-loops"],
    q: "Why has BEST's bus fleet shrunk, and what is wet lease?",
    a: "Low fares and jammed roads made the bus business lose money, and the electricity profits that once covered it were separated. Old buses were scrapped and not replaced. BEST now hires buses with drivers from private firms, called wet lease. The fleet fell from about 4,500 to 2,800 but still carries 30 lakh people a day.",
    chain: [["Fleet fell from about 4,500 to 2,800", ["4,500", "2,800", "fell", "shrunk", "fewer"]], ["Losses from low fares and traffic", ["loss", "lose money", "low fare", "traffic"]], ["Electricity profits no longer cover it", ["electricity", "separated", "cover"]], ["Wet lease: hired buses with drivers", ["wet lease", "hired", "private"]]],
    mcq: { q: "What does wet lease mean for BEST?", o: ["Hiring buses along with drivers from private operators", "Running buses in the monsoon only", "Leasing depots to private firms", "Washing buses with recycled water"] },
    bring: "When the bus is late: “BEST had 4,500 buses ten years ago. Now it has about 2,800, and most are rented.”",
    follow: "Would a reliable bus every five minutes change how you travel?",
    deeper: "BEST started bus service in 1926. It plans to make the whole fleet electric by 2027 and has received hundreds of crore rupees from the BMC and the central government to buy new buses." }
  ]));

  MV.STORIES.push(
  { id: "lasttram", assetId: "mw-last-tram", title: "The Last Tram Leaves Bori Bunder",
    hook: "On the night of 31 March 1964, people fought for a place on a tram that nobody would need the next morning.",
    setting: "Bombay in 1964. Trams had run through the city for 90 years, since the horse-drawn cars of 1874. Cars and buses were now filling the roads.",
    character: "The ordinary riders of the city, and the BEST undertaking, which had been closing tram routes one by one since 1953.",
    conflict: "Trams ran on fixed rails in the middle of the road. A stopped lorry could hold up a whole line. Buses could go around, needed no rails and cost less to keep. The sums no longer worked for trams.",
    surprise: "When the end came, the city turned out to say goodbye. The last tram from Bori Bunder to Dadar was packed beyond its doors, with people hanging from the sides and crowds cheering along the route.",
    turning: "At 10 pm the final car pulled out of Bori Bunder. It rolled slowly towards Dadar through clapping crowds and reached the depot for the last time.",
    payoff: "The next morning buses ran where the rails had been. The rails were pulled up or paved over. Only the T in BEST, for Tramways, kept the memory.",
    meaning: "Systems are usually replaced not because people stop loving them, but because the arithmetic changes. Affection and usefulness are not the same thing.",
    extra: ["Electric trams had replaced horse-drawn ones in 1907.", "Trams had carried mill workers to Parel and clerks to the Fort for three generations.", "A few cities, like Kolkata, kept their trams; in 2026 Kolkata's were also being phased out."],
    facts: [["1964", "31 march"], ["bori bunder"], ["dadar"], ["rail", "rails"], ["bus", "buses"], ["10 pm"], ["1953", "one by one"]],
    vocab: ["tramway", "depot", "arithmetic"] },

  { id: "blackout2020", assetId: "mw-islanding", title: "The Morning the Safety Switch Failed",
    hook: "Mumbai had a secret switch that had kept its lights on through every grid failure for forty years. On 12 October 2020 the switch was thrown, and the city went dark anyway.",
    setting: "Mumbai, a Monday morning during the Covid lockdown. Offices were half open, hospitals were full, and trains had just started running for essential workers.",
    character: "Tata Power's islanding system, built in 1981, and the engineers in the control rooms watching the grid.",
    conflict: "At about 10 am two state transmission substations, at Kalwa and Kharghar, tripped at nearly the same time. The failure spread through the lines feeding the city.",
    surprise: "The islanding relays worked. Mumbai cut itself off from the state grid within seconds, as designed. But it had been drawing about 1,000 MW from outside, and that supply vanished all at once.",
    turning: "An island must balance its own supply and demand instantly. The sudden gap was too large. Frequency dropped, protection tripped the city's own plants, and the island collapsed.",
    payoff: "Local trains stopped between stations. Hospitals ran on generators. Some areas were dark for two hours, others for most of the day. Tata Power said the system had saved the city 27 times before this.",
    meaning: "A safety system is designed for the failures its makers imagined. The city had grown to depend on outside power more than its island could carry.",
    extra: ["The state ordered an inquiry and an audit of Mumbai's power system.", "Mumbai's own plants include the hydro station at Khopoli, which has run since 1915, and the Trombay plant.", "After 2020, new transmission lines into the city were pushed forward to reduce the risk of a repeat."],
    facts: [["2020", "12 october"], ["island"], ["1981"], ["kalwa"], ["1,000 mw"], ["train", "trains"], ["27"]],
    vocab: ["grid", "relay", "frequency"] },

  { id: "taj2008", assetId: "mw-26-11", title: "The Staff Who Did Not Leave",
    hook: "The Taj hotel's staff knew every back door out of the building. Over three nights, almost none of them used one.",
    setting: "Mumbai, the night of 26 November 2008. The Taj Mahal Palace at Apollo Bunder was full, with about a thousand guests and five hundred staff on duty.",
    character: "The waiters, cooks, telephone operators and managers of the Taj, including general manager Karambir Kang.",
    conflict: "Ten gunmen had landed by boat and spread across the city, to CST station, Leopold Cafe, Nariman House, the Oberoi Trident and the Taj. Inside the Taj, two pairs of attackers moved through the halls with rifles and grenades.",
    surprise: "The staff could have run. Instead they turned off lights, locked guests into halls, formed human chains to move them, and put themselves between the guests and the doors. Operators stayed on the switchboard calling rooms to warn people.",
    turning: "A senior waiter, Thomas Varghese, led diners out of a restaurant and insisted on leaving last. He was killed. Karambir Kang kept directing the rescue even after his wife and two sons died in the fire on an upper floor.",
    payoff: "Commandos ended the siege on 29 November, after nearly 60 hours. 166 people had been killed across the city, including about a dozen Taj staff. The hotel reopened part of its rooms in 21 days.",
    meaning: "Courage in a crisis is often built long before, by how people are chosen, trained and treated. The Taj staff did what their habits had already prepared them to do.",
    extra: ["Harvard Business School later made a case study on why the staff behaved as they did.", "Police officers and commandos also died that night, including Hemant Karkare, Ashok Kamte, Vijay Salaskar, Tukaram Omble and Major Sandeep Unnikrishnan.", "Tukaram Omble held on to the one attacker captured alive, Ajmal Kasab, and died doing so."],
    facts: [["2008", "26 november"], ["166"], ["taj"], ["60 hours", "three nights", "29 november"], ["human chain", "between the guests"], ["karambir kang"], ["ten gunmen", "boat"]],
    vocab: ["siege", "switchboard", "commando"] }
  );

